    meta$1 = { "title": "Tiger Cave Temple Krabi (Wat Tham Suea) \u2014 Steps, Hours & Tips", "description": "Tiger Cave Temple (Wat Tham Suea) Krabi guide: the 1,237-step climb (some sources count 1,260), opening hours, dress code, how to get there from Ao Nang, and monkey safety." };
    header$1 = { "siteName": "Wat Tham Suea", "overview": "Overview", "visit": "Hours & Location", "transport": "Getting There", "history": "History & Legend", "gallery": "Photo Gallery", "reviews": "Reviews", "faq": "FAQ", "map": "Map" };
